import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CCCdsIgc.js";const p=JSON.parse('{"title":"安装与登录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),o={name:"guide/install.md"};function n(r,a,s,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="安装与登录" tabindex="-1">安装与登录 <a class="header-anchor" href="#安装与登录" aria-label="Permalink to &quot;安装与登录&quot;">​</a></h1><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li>Windows 10（1809 及以上）或 Windows 11；</li><li>Windows 10 如果提示缺少 WebView2，请 IT 装一次 WebView2 Runtime（免费）；</li><li>能访问公司的 FlyknitBuddy 服务器（由 IT 告诉你地址，一般装好就配置好了）。</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>一般由 IT 统一安装：双击安装程序，输入一次管理员密码，装好后桌面和开始菜单都有 FlyknitBuddy。</p><p>也可以在公司的 FlyknitBuddy 产品主页下载安装包，具体以 IT 的通知为准。</p><div class="tip custom-block"><p class="custom-block-title">「Windows 已保护你的电脑」</p><p>第一次运行安装程序时 Windows 可能提示「未知发布者」，点 <strong>更多信息 → 仍要运行</strong>。</p></div><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>第一次打开会弹出登录窗口，勾选同意《用户协议》《隐私政策》后：</p><ul><li><strong>加了公司域的电脑</strong>：显示当前的域账号，直接点「授权登录」；</li><li><strong>没加域的电脑</strong>：点「使用账号密码登录」，输入 Windows 账号和开机密码。密码只由本机 Windows 校验，不保存、不上传。</li></ul><p>登录后桌面右下角出现悬浮球，左下角显示你的名字和部门。</p><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><p>新版本由 IT 在后台发布，电脑会在后台自动下载。看到「重启升级」时点一下，或者下次关掉程序时会自动换好。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>「设置 → 应用 → 应用和功能」里找到 FlyknitBuddy 卸载。你的对话记录和记忆留在 <code>%APPDATA%\\Flyknit</code>，卸载不会删除。</p>',15)])])}const _=e(o,[["render",n]]);export{p as __pageData,_ as default};
